<div class="nx-page-head"><div><div class="nx-kicker">GOLDENSITE / FORM BUILDER</div><h1>Preguntar. Escuchar. Construir.</h1><p>Formularios de contacto, encuestas y registros personalizados con validación y respuestas privadas.</p></div><a class="nx-btn" href="/admin/form-builder">Nuevo formulario</a></div><?php if ($status): ?><div class="nx-alert error" role="alert"><?= $e($status) ?></div><?php endif ?>
<div class="nx-inbox"><section class="nx-panel"><div class="nx-panel-head"><h2>Formularios</h2></div><div class="nx-message-list"><?php foreach ($forms as $form): ?><a class="nx-message-item" href="?id=<?= $form['id'] ?>"><strong><?= $e($form['name']) ?></strong><span class="nx-small"><?= $form['entry_count'] ?> respuestas · <?= $form['is_active']?'Publicado':'Borrador' ?></span></a><?php endforeach ?></div></section><section class="nx-panel"><div class="nx-panel-head"><h2><?= $selected?'Editar formulario':'Crear formulario' ?></h2><?= \App\Core\GoldensiteIcon::svg('form-builder') ?></div><form method="post" class="nx-panel-body nx-stack" data-form-editor><input type="hidden" name="csrf_token" value="<?= $e($csrfToken) ?>"><input type="hidden" name="form_id" value="<?= $e($selected['id']??0) ?>"><label>Nombre<input name="name" required maxlength="150" value="<?= $e($selected['name']??'') ?>"></label><label>Dirección<input name="slug" required pattern="[a-z0-9][a-z0-9-]{2,99}" maxlength="100" value="<?= $e($selected['slug']??'') ?>" placeholder="contacto-comercial"></label><div data-form-fields></div><div class="nx-actions"><select data-add-field-type aria-label="Tipo de campo"><?php foreach (['text'=>'Texto','email'=>'Correo','textarea'=>'Texto largo','number'=>'Número','date'=>'Fecha','select'=>'Desplegable','checkbox'=>'Consentimiento'] as $type=>$label): ?><option value="<?= $type ?>"><?= $label ?></option><?php endforeach ?></select><button class="nx-btn" type="button" data-add-field>Añadir campo</button></div><input type="hidden" name="schema_json" data-form-schema value="<?= $e($selected['schema_json']??'[{"id":"nombre","label":"Nombre","type":"text","required":true,"options":[]}]') ?>"><label>Mensaje de confirmación<input name="success_message" required maxlength="500" value="<?= $e($selected['success_message']??'Gracias. Recibimos tu respuesta.') ?>"></label><label class="nx-check"><input type="checkbox" name="is_active" value="1" <?= !empty($selected['is_active'])?'checked':'' ?>>Publicar formulario</label><p class="nx-note">La publicación requiere que Goldensite Form Builder esté activo en Módulos. Los registros recopilan respuestas; no crean cuentas ni conceden permisos.</p><button class="nx-btn primary">Guardar formulario</button><?php if ($selected): ?><div class="nx-actions"><a class="nx-btn" href="/forms/<?= $e($selected['slug']) ?>" target="_blank" rel="noopener">Abrir formulario ↗</a><code>[goldensite_form id="<?= $selected['id'] ?>"]</code></div><?php endif ?></form></section></div>
<?php if ($selected): ?><section class="nx-panel" style="margin-top:24px"><div class="nx-panel-head"><h2>Respuestas</h2><a class="nx-btn" href="?id=<?= $selected['id'] ?>&amp;export=csv">Exportar CSV</a></div><div class="nx-panel-body nx-stack"><?php foreach ($entries as $entry): ?><details><summary>#<?= $entry['id'] ?> · <?= $e($entry['created_at']) ?></summary><dl data-nx-content><?php foreach (json_decode($entry['data_json'],true) as $key=>$value): ?><dt><?= $e($key) ?></dt><dd><?= nl2br($e($value)) ?></dd><?php endforeach ?></dl></details><?php endforeach ?><?php if (!$entries): ?><p>No hay resultados.</p><?php endif ?><div class="nx-actions"><?php if ($page>1): ?><a class="nx-btn" href="?id=<?= $selected['id'] ?>&amp;page=<?= $page-1 ?>">Anterior</a><?php endif ?><?php if (count($entries)===20): ?><a class="nx-btn" href="?id=<?= $selected['id'] ?>&amp;page=<?= $page+1 ?>">Siguiente</a><?php endif ?></div></div></section><?php endif ?>
<script src="/assets/admin/form-builder.js" defer></script>
